(async function(){
 const seasonal=await fetch('insolacion.json').then(r=>r.json()).catch(()=>null);const data=await fetch('data.json').then(r=>{if(!r.ok)throw Error('datos no disponibles');return r.json()});const engine=window.RouteEngine;const graph=engine.makeGraph(data);let simulated=null,last=null,mode='user';
 const map=L.map('map',{scrollWheelZoom:false}).fitBounds(data.bounds);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);
 if(seasonal&&seasonal.features){L.geoJSON(seasonal,{style:{color:'#d7a739',weight:1,fillOpacity:.1},onEachFeature:(f,l)=>l.bindPopup('Indicador municipal de insolación estival: '+escapeText(f.properties.sol_ver_m)+'<br>Dato estacional; no representa sombra en tiempo real.')}).addTo(map)}
 const bankLayer=L.layerGroup().addTo(map),routeLayer=L.layerGroup().addTo(map),markerLayer=L.layerGroup().addTo(map);data.banks.forEach(b=>L.circleMarker([b.lat,b.lon],{radius:3,color:'#337d63',fillColor:'#65a982',fillOpacity:.8,weight:1}).bindPopup('Banco registrado<br>'+escapeText(b.address)).addTo(bankLayer));
 function escapeText(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 const dest=document.getElementById('destination');const seen=new Set();data.destinations.forEach((d,i)=>{let key=d.name+'|'+d.lat+'|'+d.lon;if(seen.has(key))return;seen.add(key);let o=document.createElement('option');o.value=i;o.textContent=d.name;dest.appendChild(o)});
 const origin=document.getElementById('origin'),limit=document.getElementById('limit'),out=document.getElementById('results');limit.oninput=()=>document.getElementById('limitValue').textContent=limit.value+' m';
 function card(title,r,summary){if(!r)return `<article class="result-card"><h3>${title}</h3><p>No encontramos una ruta con ese límite en la red disponible. Prueba una distancia mayor.</p></article>`;return `<article class="result-card"><h3>${title}</h3><div class="metric"><span>Distancia del recorrido</span><strong>${Math.round(r.distance)} m</strong></div><div class="metric"><span>Mayor tramo sin descanso</span><strong>${Math.round(r.maxWithoutRest)} m</strong></div><div class="metric"><span>Descansos en el camino</span><strong>${r.stops.length}</strong></div><p>${summary}</p>${r.stops.length?`<p><strong>Puntos de descanso:</strong> ${r.stops.map(s=>escapeText(s.address||'Banco simulado')).join(' · ')}</p>`:''}</article>`}
 function compute(){routeLayer.clearLayers();markerLayer.clearLayers();const org=origin.value.split(',').map(Number),d=data.destinations[Number(dest.value)],start=engine.nearest(org,data.nodes),end=engine.nearest([d.lat,d.lon],data.nodes);if(!start.id||!end.id)return;const banks=engine.attachBanks(simulated?[...data.banks,simulated]:data.banks,data.nodes),short=engine.route(graph,data.nodes,banks,start.id,end.id,Infinity,start.distance,end.distance),rest=engine.route(graph,data.nodes,banks,start.id,end.id,Number(limit.value),start.distance,end.distance);const base=simulated?engine.route(graph,data.nodes,engine.attachBanks(data.banks,data.nodes),start.id,end.id,Number(limit.value),start.distance,end.distance):null;
 if(short)L.polyline([org,...short.coords,[d.lat,d.lon]],{color:'#98a8a1',weight:5,dashArray:'7 8'}).addTo(routeLayer);if(rest)L.polyline([org,...rest.coords,[d.lat,d.lon]],{color:'#237b60',weight:6,opacity:.9}).addTo(routeLayer);L.marker(org).bindPopup('Salida seleccionada').addTo(markerLayer);L.marker([d.lat,d.lon]).bindPopup(escapeText(d.name)).addTo(markerLayer);if(simulated)L.circleMarker([simulated.lat,simulated.lon],{radius:8,color:'#b67812',fillColor:'#e8ac3a',fillOpacity:1,weight:2}).bindPopup('Banco hipotético').addTo(markerLayer);if(rest)rest.stops.forEach(b=>L.circleMarker([b.lat,b.lon],{radius:6,color:'#fff',fillColor:b.simulated?'#e8ac3a':'#237b60',fillOpacity:1,weight:2}).bindPopup(escapeText(b.address||'Banco simulado')).addTo(markerLayer));
 let note='La ruta directa no incorpora paradas programadas.';let other='Incluye la distancia adicional para acercarse a cada banco y volver al recorrido.';let change='';if(simulated){change=base&&rest?`Con el banco simulado la distancia del recorrido cambia ${Math.round(rest.distance-base.distance)} m y el tramo máximo sin descanso cambia ${Math.round(rest.maxWithoutRest-base.maxWithoutRest)} m.`:!base&&rest?'Con el banco simulado se encuentra una ruta para el límite seleccionado.':base&&!rest?'No se ha encontrado una alternativa con el banco simulado.':'El banco simulado no cambia la disponibilidad de ruta con este límite.';}
 out.innerHTML=`<div class="result-grid">${card('Ruta más corta',short,note)}${card('Ruta con descansos',rest,other)}</div>${change?`<div class="notice"><strong>Comparación de la simulación</strong><p>${change} La ubicación es hipotética.</p></div>`:''}<p class="helper">${escapeText(d.name)} · ${escapeText(d.source)}. Incluye aproximaciones en línea recta desde el origen (${Math.round(start.distance)} m) y al destino (${Math.round(end.distance)} m). Áreas doradas: indicador municipal de insolación estival; no representa la sombra actual.</p>`;
 last={start,end,short};}
 document.getElementById('calculate').onclick=compute;function setMode(v){mode=v;document.getElementById('userTab').classList.toggle('active',v==='user');document.getElementById('cityTab').classList.toggle('active',v==='city');document.getElementById('userTab').setAttribute('aria-selected',v==='user');document.getElementById('cityTab').setAttribute('aria-selected',v==='city');document.getElementById('cityBox').classList.toggle('hidden',v!=='city')};document.getElementById('userTab').onclick=()=>setMode('user');document.getElementById('cityTab').onclick=()=>setMode('city');map.on('click',e=>{if(mode!=='city')return;const n=engine.nearest([e.latlng.lat,e.latlng.lng],data.nodes);if(n.distance>35){out.innerHTML='<div class="notice"><strong>Acerca el punto a una calle del piloto.</strong></div>';return}simulated={id:'simulado',lat:e.latlng.lat,lon:e.latlng.lng,address:'Banco simulado',simulated:true};compute()});document.getElementById('addBench').onclick=()=>{if(!last||!last.short)return;const point=last.short.coords[Math.floor(last.short.coords.length/2)];simulated={id:'simulado',lat:point[0],lon:point[1],address:'Banco simulado',simulated:true};compute()};document.getElementById('removeBench').onclick=()=>{simulated=null;compute()};compute();
})().catch(e=>{document.getElementById('results').innerHTML='<div class="notice">No se han podido cargar los datos del piloto. Comprueba la conexión y vuelve a abrir la página.</div>';console.error(e)});
